def make_seed():
    project=OUT/'seed-project'
    if project.exists():raise ValueError('seed staging already exists; use a fresh build directory')
    project.mkdir(parents=True)
    entries=source_entries()
    for name,source in entries.items():
        if not source.is_file():raise FileNotFoundError(source)
        dest=project/name;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(source,dest)
    env={**os.environ,'CHANLUN_WORKBENCH_ROOT':str(project),'PYTHONIOENCODING':'utf-8',
         'CHANLUN_V4_SAMPLE_CUTOFF':os.environ.get('CHANLUN_V4_SAMPLE_CUTOFF','2026-11-12T15:00:00+08:00')}
    p=subprocess.run([str(PYTHON),'-c',SEED_SCRIPT],cwd=project,env=env,capture_output=True,encoding='utf-8',errors='replace')
    (OUT/'seed.stdout.txt').write_text(p.stdout,encoding='utf-8');(OUT/'seed.stderr.txt').write_text(p.stderr,encoding='utf-8')
    if p.returncode:raise RuntimeError('V4 sample computation failed; see seed.stderr.txt')
    for path in project.rglob('*'):
        if path.suffix=='.json':
            value=json.loads(path.read_text(encoding='utf-8'))
            path.write_text(json.dumps(portable_value(value),ensure_ascii=False,indent=2),encoding='utf-8')
        bars=sample(125,7);session=ReferenceSession('day')
        for bar in bars:session.append(bar)
        series=Series('sz000001','day','unadjusted',tuple(bars),'tdx_live_ohlcv','raw-hash')
        meta={'restored':True,'appended':1,'rebuilt':False,'total_closed':125,
              'revision':None,'checkpoint_sha256':'checkpoint-hash'}
        meta['report']=session.snapshot(series.symbol,bars[-1].closed_at,series.source,
                                        series.adjustment,meta['checkpoint_sha256'])
        receipt={'received_at':bars[-1].closed_at,'incremental_session':meta}
        with patch('workbench.live._ingest',return_value=(LiveSession(session,125),tuple(bars),receipt,meta)) as ingest, \
             patch('workbench.reference_service.reference_report',side_effect=AssertionError('monitor replays full history')):
            value=monitor.structure_one({'symbol':'sz000001','name':'平安银行','code':'000001','exchange':'sz'},
                {'structure_mode':'day','refresh_history':False,'volume_tolerance':1},bars[100].closed_at)
        self.assertEqual(value['state'],'calculated');self.assertEqual(value['last_bar_at']['day'],bars[-1].closed_at)
        self.assertEqual(value['scan_started_at'],bars[100].closed_at)
        self.assertEqual(value['data_as_of']['day'],bars[-1].closed_at)
        self.assertTrue(all(point['age_bars']>=0 for point in value['signals']))
        self.assertEqual(value['source_receipts']['day']['incremental_session']['appended'],1)
        ingest.assert_called_once()
    def test_source_replay_rejects_today_candidate_as_past_fill(self):
        from chanmodel.causal_replay import StreamingStructure,SignalLedger
        bars=sample(120,5)
        def replay(values):
            stream=StreamingStructure();ledger=SignalLedger('day')
            for b in values:
                changed=stream.append(b);ledger.invalidate(b)
                if changed:ledger.observe(stream.snapshot(),b,stream.bars)
            return ledger.events
        self.assertEqual(replay(bars[:90]),[e for e in replay(bars) if e['observed_index']<90])


class MarketBacktestTests(unittest.TestCase):
    def test_windows_progress_sharing_denial_is_retried(self):
        with tempfile.TemporaryDirectory() as tmp:
            path=Path(tmp)/'summary.json';path.write_bytes(b'old')
            original=Path.replace;calls=[]
            def replace_once(source,target):
                calls.append(1)
                if len(calls)==1:raise PermissionError('sharing conflict')
                return original(source,target)
            with patch.object(Path,'replace',replace_once),patch('chanmodel.tdx_data.time_module.sleep'):
                atomic_bytes(path,b'new')
            self.assertEqual(path.read_bytes(),b'new');self.assertEqual(len(calls),2)
